import json,re
async def s(q,n=4,m=600,kw=None):
    r=json.loads(await web_search({"query":q}))
    print("##",q)
    for x in r[:n]:
        print(x['url']);c=x['content']
        if kw:
            for k in kw:
                for mm in list(re.finditer(k,c))[:3]:
                    print("  >>",c[max(0,mm.start()-200):mm.start()+300].replace("\n"," "))
        else: print(c[:m].replace("\n"," "))
    return r
